<?php
require_once __DIR__.'/includes/bootstrap.php';require_role(['Administrator','SACCO Official']);$pdo=db();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');if($from>$to){$tmp=$from;$from=$to;$to=$tmp;}
$summary=fetch_one($pdo,'SELECT COUNT(*) trips,COALESCE(SUM(passengers_count),0) passengers,COALESCE(SUM(total_revenue),0) revenue FROM trips WHERE trip_date BETWEEN ? AND ?',[$from,$to]);
$byRoute=fetch_all($pdo,'SELECT r.route_name,COUNT(t.trip_id) trips,COALESCE(SUM(t.total_revenue),0) revenue FROM trips t JOIN routes r ON r.route_id=t.route_id WHERE t.trip_date BETWEEN ? AND ? GROUP BY r.route_id,r.route_name ORDER BY revenue DESC',[$from,$to]);
$byDay=fetch_all($pdo,'SELECT trip_date,COUNT(*) trips,COALESCE(SUM(total_revenue),0) revenue FROM trips WHERE trip_date BETWEEN ? AND ? GROUP BY trip_date ORDER BY trip_date',[$from,$to]);
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="transitflow-report-'.$from.'-'.$to.'.csv"');$o=fopen('php://output','w');fputcsv($o,['Date range',$from.' to '.$to]);fputcsv($o,['Trips',$summary['trips']]);fputcsv($o,['Passengers',$summary['passengers']]);fputcsv($o,['Revenue KSh',$summary['revenue']]);fputcsv($o,[]);fputcsv($o,['Route','Trips','Revenue KSh']);foreach($byRoute as $r)fputcsv($o,[$r['route_name'],$r['trips'],$r['revenue']]);fclose($o);exit;}
page_header('Reports & analytics');
echo '<section class="card"><form class="toolbar" method="get"><div><label>From</label><input type="date" name="from" value="'.e($from).'"></div><div><label>To</label><input type="date" name="to" value="'.e($to).'"></div><button type="submit">Apply filters</button><a class="btn secondary" href="reports.php?from='.e($from).'&to='.e($to).'&export=csv">↓ Export CSV</a><button type="button" class="btn dark" onclick="window.print()">Print report</button></form></section>';
echo '<div class="grid"><section class="card stat-card"><span class="stat-label">Total trips</span><div class="stat-value">'.number_format($summary['trips']).'</div><small class="muted">Selected period</small></section><section class="card stat-card"><span class="stat-label">Passengers carried</span><div class="stat-value">'.number_format($summary['passengers']).'</div><small class="muted">Recorded passenger count</small></section><section class="card stat-card"><span class="stat-label">Gross revenue</span><div class="stat-value" style="font-size:21px">KSh '.number_format($summary['revenue'],2).'</div><small class="muted">Based on recorded trip totals</small></section><section class="card stat-card"><span class="stat-label">Active fleet</span><div class="stat-value">'.number_format(fetch_one($pdo,"SELECT COUNT(*) n FROM vehicles WHERE status='Active'")['n']).'</div><small class="muted">Current vehicle status</small></section></div>';
$labels=array_column($byDay,'trip_date');$vals=array_map('floatval',array_column($byDay,'revenue'));
echo '<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Revenue trend</h2><p>Daily collections for the selected period</p></div></div><div class="chart-wrap"><canvas data-chart=\''.e(json_encode(['type'=>'line','labels'=>$labels,'datasets'=>[['label'=>'Revenue KSh','data'=>$vals,'borderColor'=>'#ed6a24','backgroundColor'=>'rgba(237,106,36,.10)']]] )).'\'></canvas></div></section><section class="card"><div class="card-head"><div><h2>Revenue by route</h2><p>Performance comparison</p></div></div><div class="chart-wrap"><canvas data-chart=\''.e(json_encode(['type'=>'bar','labels'=>array_column($byRoute,'route_name'),'datasets'=>[['label'=>'Revenue KSh','data'=>array_map('floatval',array_column($byRoute,'revenue')),'backgroundColor'=>'#ed9a6c','fill'=>false]]])).'\'></canvas></div></section></div>';
echo '<section class="card"><div class="card-head"><div><h2>Route performance</h2><p>Trip volume and revenue by route</p></div></div><div class="table-wrap"><table><thead><tr><th>Route</th><th>Trips</th><th>Revenue</th><th>Average per trip</th></tr></thead><tbody>';
if(!$byRoute)echo '<tr><td colspan="4"><div class="empty-state"><b>No records for this period</b>Try widening the date range.</div></td></tr>';
foreach($byRoute as $r)echo '<tr><td><b>'.e($r['route_name']).'</b></td><td>'.(int)$r['trips'].'</td><td>'.money_kes($r['revenue']).'</td><td>'.money_kes($r['trips']?$r['revenue']/$r['trips']:0).'</td></tr>';
echo '</tbody></table></div></section>';page_footer();
